(async () => {
  let state = await lf.ready;
  const form = document.getElementById('scale-form');
  const ingredientInput = document.getElementById('ingredient');
  const quantityInput = document.getElementById('quantity');
  const originalInput = document.getElementById('original');
  const targetInput = document.getElementById('target');
  const calcBtn = document.getElementById('calc-btn');
  const saveBtn = document.getElementById('save-btn');
  const resultContainer = document.getElementById('result-container');
  const resultValue = document.getElementById('result-value');
  const previewNotice = document.getElementById('preview-notice');
  const errorContainer = document.getElementById('error-container');
  const savedListContainer = document.getElementById('saved-list-container');

  let lastCalculation = null;

  function clearResult() {
    lastCalculation = null;
    resultContainer.style.display = 'none';
    saveBtn.disabled = true;
    errorContainer.textContent = '';
  }

  [ingredientInput, quantityInput, originalInput, targetInput].forEach(input => {
    input.addEventListener('input', clearResult);
  });

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errorContainer.textContent = '';

    const ingredient = ingredientInput.value.trim();
    const quantity = parseFloat(quantityInput.value);
    const originalServings = parseFloat(originalInput.value);
    const targetServings = parseFloat(targetInput.value);

    if (!state.permissions.canUseTools) {
      resultContainer.style.display = 'flex';
      resultValue.textContent = 'Publish required';
      previewNotice.style.display = 'block';
      previewNotice.textContent = 'Publish to run tool.';
      saveBtn.disabled = true;
      return;
    }

    try {
      calcBtn.disabled = true;
      calcBtn.textContent = 'Calculating...';
      const res = await lf.runTool('scale_ingredient', 1, {
        quantity,
        originalServings,
        targetServings
      });

      const scaled = res.result.scaledQuantity;
      lastCalculation = {
        ingredient,
        quantity,
        originalServings,
        targetServings,
        scaledQuantity: scaled
      };

      resultValue.textContent = `${scaled} g`;
      previewNotice.style.display = 'none';
      resultContainer.style.display = 'flex';
      saveBtn.disabled = false;
    } catch (err) {
      errorContainer.innerHTML = `<div class="error-msg">Calculation failed: ${err.message || 'Unknown error'}</div>`;
    } finally {
      calcBtn.disabled = false;
      calcBtn.textContent = 'Calculate';
    }
  });

  saveBtn.addEventListener('click', async () => {
    if (!lastCalculation) return;
    try {
      saveBtn.disabled = true;
      saveBtn.textContent = 'Saving...';
      state = await lf.create({
        ingredient: lastCalculation.ingredient,
        quantity: lastCalculation.quantity,
        original: lastCalculation.originalServings,
        target: lastCalculation.targetServings,
        scaled: lastCalculation.scaledQuantity
      });
      renderRecords(state);
      clearResult();
      form.reset();
    } catch (err) {
      errorContainer.innerHTML = `<div class="error-msg">Save failed: ${err.message || 'Unknown error'}</div>`;
    } finally {
      saveBtn.disabled = false;
      saveBtn.textContent = 'Save Result';
    }
  });

  function renderRecords(currentState) {
    const records = currentState.records || [];
    if (records.length === 0) {
      savedListContainer.innerHTML = '<div class="empty-state">No saved calculations yet. Scale and save an ingredient above.</div>';
      return;
    }

    savedListContainer.innerHTML = '';
    records.forEach(rec => {
      const vals = rec.values;
      const item = document.createElement('div');
      item.className = 'saved-item';

      const info = document.createElement('div');
      info.className = 'saved-info';
      info.innerHTML = `
        <h3>${escapeHtml(vals.ingredient || 'Ingredient')}</h3>
        <p>${vals.quantity}g (${vals.original} servings) ➔ <strong>${vals.scaled}g</strong> (${vals.target} servings)</p>
      `;

      const delBtn = document.createElement('button');
      delBtn.className = 'btn-secondary';
      delBtn.style.padding = '0.4rem 0.75rem';
      delBtn.style.fontSize = '0.85rem';
      delBtn.textContent = 'Delete';
      delBtn.addEventListener('click', async () => {
        try {
          state = await lf.remove(rec.id);
          renderRecords(state);
        } catch (err) {
          alert('Failed to delete: ' + (err.message || 'Unknown error'));
        }
      });

      item.appendChild(info);
      item.appendChild(delBtn);
      savedListContainer.appendChild(item);
    });
  }

  function escapeHtml(str) {
    return str.replace(/[&<>'"]/g, 
      tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
    );
  }

  lf.subscribe(next => {
    state = next;
    renderRecords(state);
  });

  renderRecords(state);
  await lf.reportReady();
})();

